const defs = @import("definitions.zig");
const trans = @import("transitions.zig");
const luts = @import("luts.zig");
pub const B = defs.block;
pub const Pattern = enum { leading, alternating, trailing };
pub const Spec = struct { compressed: usize, pattern: Pattern = .leading, barriers: bool = true, groups:usize=4 };
fn aesMul(a_in: u8, b_in: u8) u8 {
    var a = a_in;
    var b = b_in;
    var out: u8 = 0;
    for (0..8) |_| {
        if (b & 1 != 0) out ^= a;
        const high = a & 0x80 != 0;
        a = (a << 1) ^ @as(u8, if (high) 0x1b else 0);
        b >>= 1;
    }
    return out;
}
const basis = blk: {
    var out: [8]u8 = undefined;
    out[0] = 1;
    for (1..8) |i| out[i] = aesMul(out[i - 1], 0x30);
    break :blk out;
};
pub fn toAes(x: u8) u8 {
    var out: u8 = 0;
    for (0..8) |i| if ((x >> @intCast(i)) & 1 != 0) {
        out ^= basis[i];
    };
    return out;
}
const inverse_map = blk: {
    @setEvalBranchQuota(100000);
    var out: [256]u8 = undefined;
    for (0..256) |i| out[toAes(@intCast(i))] = @intCast(i);
    break :blk out;
};
fn inverseMatrix() u64 {
    @setEvalBranchQuota(100000);
    var out: u64 = 0;
    for (0..8) |j| {
        var row: u8 = 0;
        for (0..8) |i| {
            const mapped = inverse_map[@as(u8, 1) << @intCast(i)];
            row |= ((mapped >> @intCast(j)) & 1) << @intCast(i);
        }
        out |= @as(u64, row) << @intCast((7 - j) * 8);
    }
    return out;
}
const encoded_pi = blk: {
    @setEvalBranchQuota(100000);
    var out: [256]u8 = undefined;
    for (0..256) |i| out[i] = toAes(defs.pi_inv_table[i]);
    break :blk out;
};
const encoded_raw=blk:{@setEvalBranchQuota(100000);var out:[256]u8=undefined;for(0..256)|i|out[i]=toAes(@intCast(i));break :blk out;};
const columns = blk: {
    @setEvalBranchQuota(1000000);
    var out: [16]B = undefined;
    for (0..16) |i| {
        var unit: B = @splat(0);
        unit[i] = 1;
        const col = trans.l_inv_trans(unit);
        for (0..16) |j| out[i][j] = toAes(col[j]);
    }
    break :blk out;
};
inline fn mul(a: B, b: B) B {
    return asm ("vgf2p8mulb %[b], %[a], %[out]"
        : [out] "=v" (-> B),
        : [a] "v" (a),
          [b] "vm" (b),
    );
}
inline fn inverseAffine(a: B) B {
    const matrix: @Vector(2, u64) = @splat(comptime inverseMatrix());
    return asm ("vgf2p8affineqb $0, %[matrix], %[a], %[out]"
        : [out] "=v" (-> B),
        : [a] "v" (a),
          [matrix] "vm" (matrix),
    );
}
pub inline fn contribution(comptime pos: usize, value: u8) B {
    return inverseAffine(mul(@splat(encoded_pi[value]), columns[pos]));
}
inline fn compressed(comptime spec: Spec, comptime i: usize) bool {
    return switch (spec.pattern) {
        .leading => i < spec.compressed,
        .trailing => i >= 16 - spec.compressed,
        .alternating => i % 2 == 0,
    };
}
inline fn gpIdentity(a: u64) u64 {
    return asm (""
        : [out] "=r" (-> u64),
        : [in] "0" (a),
    );
}
inline fn roundWords(comptime spec: Spec, words: [2]u64, seed: [2]u64, comptime first: bool) [2]u64 {
    var aes: B = @splat(0);
    inline for (0..16) |i| if (compressed(spec, i)) {
        const index: u8 = @truncate(words[i / 8] >> @as(u6, @intCast(i % 8 * 8)));
        aes ^= mul(@splat(if(first)encoded_raw[index]else encoded_pi[index]), columns[i]);
    };
    const positions = comptime blk: {
        var out: [16 - spec.compressed]usize = undefined;
        var j: usize = 0;
        for (0..16) |i| if (!compressed(spec, i)) {
            out[j] = i;
            j += 1;
        };
        break :blk out;
    };
    var accum: [spec.groups][2]u64 = .{.{ 0, 0 }} ** spec.groups;
    accum[0] = seed;
    inline for (0..spec.groups) |group| {
        inline for (positions, 0..) |i, j| {
            if (j % spec.groups == group) {
                const offset: usize = if(first) @as(usize,defs.pi_table[@as(u8,@truncate(words[i/8]>>@as(u6,@intCast(i%8*8))))])<<4 else if (i % 8 == 0) (words[i / 8] << 4) & 0xff0 else (words[i / 8] >> @as(u6, @intCast(i % 8 * 8 - 4))) & 0xff0;
                const entry: *const [2]u64 = @ptrFromInt(@intFromPtr(&luts.ls_inv_trans_lut[i]) + offset);
                accum[group][0] ^= entry[0];
                accum[group][1] ^= entry[1];
            }
        }
        accum[group][0] = gpIdentity(accum[group][0]);
        accum[group][1] = gpIdentity(accum[group][1]);
    }
    var lo = accum[0][0];
    var hi = accum[0][1];
    inline for (1..spec.groups) |g| {
        lo ^= accum[g][0];
        hi ^= accum[g][1];
    }
    const low = gpIdentity(lo);
    const high = gpIdentity(hi);
    const partial: [2]u64 = @bitCast(inverseAffine(aes));
    return .{ gpIdentity(low ^ partial[0]), gpIdentity(high ^ partial[1]) };
}
pub inline fn rawContribution(comptime pos:usize,value:u8)B{return inverseAffine(mul(@splat(encoded_raw[value]),columns[pos]));}
inline fn inverseSubstitute(words:[2]u64)[2]u64{
 var out:[2]u64=.{0,0};inline for(0..16)|i|{const shift:u6=@intCast(i%8*8);out[i/8]|=@as(u64,defs.pi_inv_table[@as(u8,@truncate(words[i/8]>>shift))])<<shift;}return out;
}
pub fn decrypt(comptime spec:Spec,comptime vector_end:bool,keys:*const[10]B,inverse_keys:*const[10]B,msg:*align(16)B)void{
 @setRuntimeSafety(false);var words:[2]u64=@bitCast(msg.*);
 inline for(0..9)|r|words=roundWords(spec,words,@bitCast(inverse_keys[9-r]),r==0);
 msg.*=(if(vector_end)@import("scalar_vbmi.zig").inverseSbox(@bitCast(words))else @as(B,@bitCast(inverseSubstitute(words))))^keys[0];
}
