const encoded_inverse = blk: {
    @setEvalBranchQuota(100000);
    var out: [256]u8 = undefined;
    for (0..256) |i| out[i] = toAes(defs.pi_inv_table[i]);
    break :blk out;
};
const encoded_raw_inverse = blk: {
    @setEvalBranchQuota(100000);
    var out: [256]u8 = undefined;
    for (0..256) |i| out[i] = toAes(@intCast(i));
    break :blk out;
};
const inverse_columns = blk: {
    @setEvalBranchQuota(1000000);
    var out: [16]B = undefined;
    for (0..16) |i| {
        var unit: B = @splat(0);
        unit[i] = 1;
        const col = trans.l_inv_trans(unit);
        for (0..16) |j| out[i][j] = toAes(col[j]);
    }
    break :blk out;
};
inline fn inverseRoundWords(words: [2]u64, seed: [2]u64, comptime first: bool) [2]u64 {
    var aes: B = @splat(0);
    inline for (0..5) |i| {
        const index: u8 = @truncate(words[i / 8] >> @as(u6, @intCast(i % 8 * 8)));
        aes ^= mul(@splat(if (first) encoded_raw_inverse[index] else encoded_inverse[index]), inverse_columns[i]);
    }
    var accum: [3][2]u64 = .{.{ 0, 0 }} ** 3;
    accum[0] = seed;
    inline for (0..3) |group| {
        inline for (5..16) |i| {
            if ((i - 5) % 3 == group) {
                const offset: usize = if (first) @as(usize, defs.pi_table[@as(u8, @truncate(words[i / 8] >> @as(u6, @intCast(i % 8 * 8))))]) << 4 else if (i % 8 == 0) (words[i / 8] << 4) & 0xff0 else (words[i / 8] >> @as(u6, @intCast(i % 8 * 8 - 4))) & 0xff0;
                const entry: *const [2]u64 = @ptrFromInt(@intFromPtr(&luts.ls_inv_trans_lut[i]) + offset);
                accum[group][0] ^= entry[0];
                accum[group][1] ^= entry[1];
            }
        }
        accum[group][0] = gpIdentity(accum[group][0]);
        accum[group][1] = gpIdentity(accum[group][1]);
    }
    var lo = accum[0][0];
    var hi = accum[0][1];
    inline for (1..3) |g| {
        lo ^= accum[g][0];
        hi ^= accum[g][1];
    }
    const low = gpIdentity(lo);
    const high = gpIdentity(hi);
    const partial: [2]u64 = @bitCast(inverseAffine(aes));
    return .{ gpIdentity(low ^ partial[0]), gpIdentity(high ^ partial[1]) };
}

const W = @Vector(64, u8);
inline fn permute2(a: W, indices: W, b: W) W {
    return asm ("vpermi2b %[b], %[a], %[indices]"
        : [out] "=v" (-> W),
        : [indices] "0" (indices),
          [a] "v" (a),
          [b] "vm" (b),
    );
}
inline fn inverseSubstitute(a: B) B {
    const table = defs.pi_inv_table;
    const indices: W = @bitCast([4]B{ a, undefined, undefined, undefined });
    const low = permute2(table[0..64].*, indices, table[64..128].*);
    const high = permute2(table[128..192].*, indices, table[192..256].*);
    const result = @select(u8, indices < @as(W, @splat(128)), low, high);
    return @as([4]B, @bitCast(result))[0];
}
pub fn decrypt(keys: *const [10]B, inverse_keys: *const [10]B, msg: *align(16) B) void {
    @setRuntimeSafety(false);
    var words: [2]u64 = @bitCast(msg.*);
    inline for (0..9) |round| words = inverseRoundWords(words, @bitCast(inverse_keys[9 - round]), round == 0);
    msg.* = inverseSubstitute(@bitCast(words)) ^ keys[0];
}

