const std=@import("std");
const k=@import("kuznechik.zig");
const scalar=@import("scalar.zig");
const scalar_vbmi=@import("scalar_vbmi.zig");
const h=@import("hybrid_tuned.zig");
const gp=@import("hybrid_gpr.zig");
const samples=31;
const N=500000;
const B=k.block;
fn baseline(c:*const k.Cipher,msg:*align(16)B)void{c.decrypt(msg);}
fn direct_scalar(c:*const k.Cipher,msg:*align(16)B)void{scalar.decrypt(&c.ik,&c.ik_inv,msg);}
fn vbmi_scalar(c:*const k.Cipher,msg:*align(16)B)void{scalar_vbmi.decrypt(&c.ik,&c.ik_inv,msg);}
fn Shape(comptime func:anytype)type{return struct{
 fn shaped(self:k.Cipher,msg:*align(16)B)void{func(&self,msg);}
 fn run(c:*const k.Cipher,msg:*align(16)B)void{shaped(c.*,msg);}
};}
const Outcome=struct{elapsed:u64,output:B};
noinline fn run(comptime func:anytype,c:*const k.Cipher,initial:B)!Outcome{
 var msg:B align(16)=initial;for(0..N/8)|_|func(c,&msg);msg=initial;
 var timer=try std.time.Timer.start();for(0..N)|_|func(c,&msg);const ns=timer.read();std.mem.doNotOptimizeAway(msg);return .{.elapsed=ns,.output=msg};
}
fn compare(comptime name:[]const u8,comptime func:anytype,c:*const k.Cipher,initial:B)!void{
 var a:[samples]u64=undefined;var b:[samples]u64=undefined;var ratios:[samples]f64=undefined;
 for(0..samples)|i|{
  var base:Outcome=undefined;var candidate:Outcome=undefined;
  if(i%2==0){base=try run(baseline,c,initial);candidate=try run(func,c,initial);}else{candidate=try run(func,c,initial);base=try run(baseline,c,initial);}
  if(!std.meta.eql(base.output,candidate.output))return error.CipherMismatch;
  a[i]=base.elapsed;b[i]=candidate.elapsed;ratios[i]=@as(f64,@floatFromInt(b[i]))/@as(f64,@floatFromInt(a[i]));
 }
 var sa=a;var sb=b;var sr=ratios;std.mem.sort(u64,&sa,{},std.sort.asc(u64));std.mem.sort(u64,&sb,{},std.sort.asc(u64));std.mem.sort(f64,&sr,{},std.sort.asc(f64));
 std.debug.print("{{\"candidate\":\"{s}\",\"pairs\":{d},\"baseline_ns\":{d:.4},\"candidate_ns\":{d:.4},\"median_paired_ratio\":{d:.6},\"baseline_elapsed\":[",.{name,samples,@as(f64,@floatFromInt(sa[samples/2]))/N,@as(f64,@floatFromInt(sb[samples/2]))/N,sr[samples/2]});
 for(a,0..)|v,i|std.debug.print("{s}{d}",.{if(i==0)""else",",v});std.debug.print("],\"candidate_elapsed\":[",.{});for(b,0..)|v,i|std.debug.print("{s}{d}",.{if(i==0)""else",",v});std.debug.print("]}}\n",.{});
}
pub fn main()!void{
 var key:k.key=undefined;std.crypto.random.bytes(std.mem.asBytes(&key));std.mem.doNotOptimizeAway(&key);const c=k.Cipher.init(key);
 var initial:B=undefined;std.crypto.random.bytes(std.mem.asBytes(&initial));
 try compare("dense_N5_g3_VBMI_API",Shape(h.N5_g3_end1).run,&c,initial);
 try compare("dense_N5_g4_VBMI_API",Shape(h.N5_g4_end1).run,&c,initial);
 try compare("dense_N5_g3_scalar_API",Shape(h.N5_g3_end0).run,&c,initial);
 try compare("dense_N6_g3_VBMI_API",Shape(h.N6_g3_end1).run,&c,initial);
 try compare("original_N5_VBMI_API",Shape(gp.fullGP5_v1).run,&c,initial);
}

