const std=@import("std");
const k=@import("kuznechik.zig");
const h=@import("hybrid_endpoints.zig");
const f=@import("hybrid_field.zig");
const scalar_vbmi=@import("scalar_vbmi.zig");
const gp=@import("hybrid_tuned.zig");
const definitions=@import("definitions.zig");
const luts=@import("luts.zig");
const t=@import("transitions.zig");
test "hybrid GFNI contribution matches every inverse LUT row byte"{
 if(comptime !@import("gfni.zig").supported)return error.SkipZigTest;
 inline for(0..16)|row|for(0..256)|v|{
 try std.testing.expectEqual(luts.ls_inv_trans_lut[row][v],gp.contribution(row,@intCast(v)));
 try std.testing.expectEqual(luts.ls_inv_trans_lut[row][definitions.pi_table[v]],gp.rawContribution(row,@intCast(v)));
 try std.testing.expectEqual(luts.ls_inv_trans_lut[row][v],f.contribution(row,@intCast(v)));
 try std.testing.expectEqual(luts.ls_inv_trans_lut[row][v],f.tableContribution(row,@intCast(v)));
 try std.testing.expectEqual(luts.ls_inv_trans_lut[row][definitions.pi_table[v]],f.rawContribution(row,@intCast(v)));
};
}
fn basic(c:*const k.Cipher,input:k.block)k.block{
 var state=input^c.ik[9];for(0..9)|r|state=t.s_inv_trans(t.l_inv_trans(state))^c.ik[8-r];return state;
}
test "hybrid variants decrypt arbitrary ciphertext like basic transformations"{
 if(comptime !@import("gfni.zig").supported)return error.SkipZigTest;
 var prng=std.Random.DefaultPrng.init(0x6879627269646465);const random=prng.random();
 for(0..4)|_|{var key:k.key=undefined;random.bytes(std.mem.asBytes(&key));const c=k.Cipher.init(key);
  for(0..16)|_|{var input:k.block align(16)=undefined;random.bytes(std.mem.asBytes(&input));const expected=basic(&c,input);
   var control:k.block align(16)=input;scalar_vbmi.decrypt(&c.ik,&c.ik_inv,&control);try std.testing.expectEqual(expected,control);
   inline for(gp.cases)|case|{var actual:k.block align(16)=input;case.run(&c,&actual);try std.testing.expectEqual(expected,actual);}
  }
 }
 for(0..16)|_|{var key:k.key=undefined;random.bytes(std.mem.asBytes(&key));const c=k.Cipher.init(key);
  for(0..64)|_|{var input:k.block align(16)=undefined;random.bytes(std.mem.asBytes(&input));var expected:k.block align(16)=input;c.decrypt(&expected);
   inline for(gp.cases)|case|{var actual:k.block align(16)=input;case.run(&c,&actual);try std.testing.expectEqual(expected,actual);}
  }
 }
}

test "VBMI endpoint control matches every inverse Sbox value"{
 if(comptime !@import("gfni.zig").supported)return error.SkipZigTest;
 for(0..16)|chunk|{var input:k.block=undefined;var expected:k.block=undefined;for(0..16)|i|{input[i]=@intCast(chunk*16+i);expected[i]=definitions.pi_inv_table[input[i]];}try std.testing.expectEqual(expected,scalar_vbmi.inverseSbox(input));}
}

